source='''from collections import Counter


def transform(grid):
    """Mark missing cells on a broken rectangular outline with color 2."""
    h, w = len(grid), len(grid[0])
    counts = Counter(value for row in grid for value in row)
    background = counts.most_common(1)[0][0]
    foreground = max((count, color) for color, count in counts.items()
                     if color != background)[1]

    points = [(r, c) for r in range(h) for c in range(w)
              if grid[r][c] == foreground]
    min_r = min(r for r, _ in points)
    max_r = max(r for r, _ in points)
    min_c = min(c for _, c in points)
    max_c = max(c for _, c in points)
    output = [row[:] for row in grid]

    # Restore missing cells along the outer bounding-box sides.
    for c in range(min_c, max_c + 1):
        if output[min_r][c] == background:
            output[min_r][c] = 2
        if output[max_r][c] == background:
            output[max_r][c] = 2
    for r in range(min_r, max_r + 1):
        if output[r][min_c] == background:
            output[r][min_c] = 2
        if output[r][max_c] == background:
            output[r][max_c] = 2

    # Some examples also contain a dense interior straight stroke. Mark its
    # small gaps without joining sparse, unrelated points across the grid.
    for r in range(min_r + 1, max_r):
        columns = [c for c in range(min_c, max_c + 1)
                   if grid[r][c] == foreground]
        if len(columns) >= 6 and len(columns) / (columns[-1] - columns[0] + 1) >= 0.70:
            for left, right in zip(columns, columns[1:]):
                for c in range(left + 1, right):
                    if output[r][c] == background:
                        output[r][c] = 2

    for c in range(min_c + 1, max_c):
        rows = [r for r in range(min_r, max_r + 1)
                if grid[r][c] == foreground]
        if len(rows) >= 6 and len(rows) / (rows[-1] - rows[0] + 1) >= 0.70:
            for top, bottom in zip(rows, rows[1:]):
                for r in range(top + 1, bottom):
                    if output[r][c] == background:
                        output[r][c] = 2

    return output
